def parse_query_terms(frame, query, fields):
    query_words = set(query.split())
    query_words.difference_update(stopwords.words("english"))
    query_words = [WordNetLemmatizer().lemmatize(word) for word in query_words]
    num_search_terms = len(query_words)
    search_terms = defaultdict(list)
    for field in fields:
        post_arr = get_field(frame, field)
        for doc in post_arr:
            doc_words = set(doc.split())
            doc_words.difference_update(stopwords.words("english"))
            doc_words = [WordNetLemmatizer().lemmatize(word) for word in doc_words]
            scores = jaccard_distance(query_words, doc_words, w=1.0)
            if scores > 0.0:
                search_terms[field].append((doc, scores))
    term_centric = num_search_terms > 0
    return num_search_terms, search_terms, term_centric

